&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;a0bgh-0-0&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;p&quot; data-block=&quot;true&quot; data-editor=&quot;dk51c&quot; data-offset-key=&quot;32ils-0-0&quot;&gt;
