&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;ao49b&quot; data-offset-key=&quot;8vue0-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;8vue0-0-0&quot;&gt;&lt;span data-offset-key=&quot;8vue0-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;5+ years with cloud service providers like AWS, Azure, or Google Cloud&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;ao49b&quot; data-offset-key=&quot;852q6-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;852q6-0-0&quot;&gt;&lt;span data-offset-key=&quot;852q6-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Kubernetes and Cloud Native Associate or equivalent certification&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;ao49b&quot; data-offset-key=&quot;a3u4q-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;a3u4q-0-0&quot;&gt;&lt;span data-offset-key=&quot;a3u4q-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Knowledge of service mesh architectures such as Istio or Linkerd&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;ao49b&quot; data-offset-key=&quot;7q1oc-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;7q1oc-0-0&quot;&gt;&lt;span data-offset-key=&quot;7q1oc-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Hands-on experience with cloud security practices and tools&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;ao49b&quot; data-offset-key=&quot;d8cj4-0-0&quot;&gt;
