&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; style=&quot;text-align: justify;&quot; data-offset-key=&quot;8dq6m-0-0&quot;&gt;&lt;span data-offset-key=&quot;8dq6m-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Background in both detection engineering and incident response—understanding how hunts feed detections and how incidents inform future hunts.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; style=&quot;text-align: justify;&quot; data-block=&quot;true&quot; data-editor=&quot;cfs7v&quot; data-offset-key=&quot;57iqd-0-0&quot;&gt;
