&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;4c53&quot; data-offset-key=&quot;3bdin-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;3bdin-0-0&quot;&gt;&lt;span id=&quot;popover-trigger-:r4f:&quot; class=&quot;chakra-text css-bcri66&quot;&gt;&lt;span data-offset-key=&quot;3bdin-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Operational Discipline:&lt;/span&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;3bdin-0-1&quot;&gt;&lt;span data-text=&quot;true&quot;&gt; Solid analytical capability and data-driven decision-making.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span data-offset-key=&quot;3bdin-1-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt; Expertise in applying structured methodologies (e.g., MEDDPICC) to complex direct and joint sales cycles.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
